// monic_presentation.go — the chapter's monic presentation statements.

package kaehler

import (
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_division"
	"github.com/euc-ai/xugo/library/registry"
)

// MonicEvaluationPresentation — The relative differential module of an exact monic presentation is the derivative quotient, generated by dy.
var MonicEvaluationPresentation = monicEvaluationPresentationThm{family.Add(registry.ProofEntry{
	Name: "MonicEvaluationPresentation",
	Key:  "prop_b1d0d1e5fbcae450",
	Reading: "The exact evaluation kernel supplies the sole differential relation F′(y)dy=0. The " +
		"derivative may vanish, in which case the quotient is B and the differential module is free on dy.",
	Deps: []registry.EntryLike{
		KaehlerUniversalExists,
		KaehlerUniversalUnique,
		UniversalDerivationIsDerivation,
		KaehlerSpan,
		polynomial.DerivativeMul,
		polynomial.DerivativeAdd,
		polynomial_division.MonicDivisionAlgorithm,
		module_homomorphism.ModuleIsomorphismDef,
	},
	Build: family.Card(Statement{
		Binders: "∀L:field_on(A). ∀S B:set(A). ∀y:A. ∀F:(num → A).",
		Hypotheses: []string{
			"S ⊆ B",
			"subring(field_ring(L), S)",
			"subring(field_ring(L), B)",
			"y ∈ B",
			"polynomial_over(S, F)",
			"polynomial_monic(F)",
			"0 < polynomial_degree(F)",
			"B = polynomial_image(field_ring(L), S, y)",
			"∀p:(num → A). " +
				"    polynomial_over(S, p) ⇒ " +
				"    (polynomial_eval(p, y) = L.zero ⇔ polynomial_divides(restrict_ring(field_ring(L), S), F, p))",
		},
		Conclusion: "∃h:(set(A) → set(A → A)). " +
			"    module_isomorphism(restrict_ring(field_ring(L), B), " +
			"        quotient_module(restrict_module(regular_module(field_ring(L)), B), " +
			"            image(L.mul(polynomial_eval(polynomial_derivative(F), y)), B)), " +
			"        kaehler_module(restrict_ring(field_ring(L), S), " +
			"            restrict_ring(field_ring(L), B), " +
			"            λa:A. a), " +
			"        h) ∧ " +
			"    (∀b:A. " +
			"        b ∈ B ⇒ " +
			"        h(left_coset(L.add, " +
			"                b, " +
			"                image(L.mul(polynomial_eval(polynomial_derivative(F), y)), B))) = " +
			"        kaehler_module(restrict_ring(field_ring(L), S), " +
			"            restrict_ring(field_ring(L), B), " +
			"            λa:A. a).smul(b, " +
			"            universal_derivation(restrict_ring(field_ring(L), S), " +
			"                restrict_ring(field_ring(L), B), " +
			"                λa:A. a, " +
			"                y)))",
	},
		"Polynomial differentiation descends to an S-derivation B→B/(F′(y)): replacing p by p+Fq "+
			"changes the derivative value by F′(y)q(y). UniversalExists and UniversalUnique make it "+
			"inverse to [b]↦b·dy, using KaehlerSpan. No nonzero derivative hypothesis is needed."),
})}
